import timeimport loggingimport ccxtimport analyzer as baselogging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("trader_execution.log"), logging.StreamHandler()],    force=True,)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)MIN_ROI_PCT = 0.1CHECK_INTERVAL_SEC = 60WITHDRAWAL_RETRY_ATTEMPTS = 3WITHDRAWAL_RETRY_BASE_DELAY = 5ORDER_RETRY_ATTEMPTS = 3ORDER_RETRY_BASE_DELAY = 3ORDER_POLL_INTERVAL_SEC = 3ORDER_POLL_TIMEOUT_SEC = 60BALANCE_ARRIVAL_TOLERANCE = 0.98FATAL_EXCHANGE_ERRORS = (    ccxt.AuthenticationError,    ccxt.PermissionDenied,    ccxt.AccountSuspended,    ccxt.InvalidAddress,    ccxt.BadSymbol,    ccxt.NotSupported,)class TradeAborted(Exception):    pass# ----------------------------------------------------------------------#  Database helpers (unchanged)# ----------------------------------------------------------------------def load_all_trade_coins() -> list:    sb = base._get_supabase_cached()    try:        rows = sb.table("trade_coins").select("*").execute()        return rows.data or []    except Exception as e:        log.warning(f"trade_coins fetch failed: {str(e)[:200]}")        return []def delete_trade_coin(row_id) -> bool:    sb = base._get_supabase_cached()    try:        sb.table("trade_coins").delete().eq("id", row_id).execute()        return True    except Exception as e:        log.warning(f"trade_coins delete failed for id {row_id}: {str(e)[:200]}")        return Falsedef parse_buy_sell_exchanges(exchange_field: str):    if not exchange_field or "/" not in exchange_field:        return None, None    buy_ex, sell_ex = exchange_field.split("/", 1)    return buy_ex.strip(), sell_ex.strip()def parse_usdt_transfer_fee(value: str):    if not value or "/" not in value:        return None, None    network, fee = value.rsplit("/", 1)    try:        return network.strip(), float(fee)    except ValueError:        return network.strip(), Nonedef get_capital_holder() -> str:    state = base.load_bot_state()    return state.get("holds_usdt")WALLET_TYPES = {    'Bybit':   ['unified', 'spot', 'swap', 'funding'],    'Bitget':  ['spot', 'swap'],    'MEXC':    ['spot', 'swap'],    'BingX':   ['spot', 'swap', 'funding'],    'KuCoin':  ['main', 'trade', 'future'],    'CoinEx':  ['spot', 'swap', 'margin'],    'BitMart': ['spot', 'swap', 'account'],    'OKX':     ['spot', 'swap', 'funding'],    'LBank':   ['spot'],}def _extract_usdt(balance):    if not isinstance(balance, dict):        return None    usdt = balance.get('USDT')    if isinstance(usdt, dict) and any(k in usdt for k in ('free', 'used', 'total')):        return usdt.get('free'), usdt.get('used'), usdt.get('total')    free_map  = balance.get('free')  or {}    used_map  = balance.get('used')  or {}    total_map = balance.get('total') or {}    if 'USDT' in total_map or 'USDT' in free_map or 'USDT' in used_map:        return free_map.get('USDT'), used_map.get('USDT'), total_map.get('USDT')    for code in set(list(total_map) + list(free_map) + list(used_map)):        if isinstance(code, str) and code.upper() == 'USDT':            return free_map.get(code), used_map.get(code), total_map.get(code)    return Nonedef _extract_asset(balance, code):    if not isinstance(balance, dict):        return None    code = code.upper()    entry = balance.get(code)    if isinstance(entry, dict) and any(k in entry for k in ('free', 'used', 'total')):        return entry.get('free')    free_map = balance.get('free') or {}    for c, v in free_map.items():        if isinstance(c, str) and c.upper() == code:            return v    return Nonedef get_available_usdt_balance(exchange_name: str, raise_fatal: bool = False):    ex = base.ensure_exchange(exchange_name)    if ex is None:        if raise_fatal:            raise TradeAborted(f"{exchange_name}: could not initialize exchange for balance check")        log.warning(f"{exchange_name}: could not initialize exchange for balance check")        return None, None    candidates = []    try:        bal = ex.fetch_balance()        usdt = _extract_usdt(bal)        if usdt and usdt[0]:            candidates.append(('overview', usdt[0]))    except FATAL_EXCHANGE_ERRORS as e:        if raise_fatal:            raise TradeAborted(f"{exchange_name}: fatal error checking USDT balance — {type(e).__name__}: {str(e)[:200]}")        log.error(f"{exchange_name}: fatal error checking USDT balance — {type(e).__name__}: {str(e)[:200]}")    except Exception as e:        log.warning(f"{exchange_name} overview fetch_balance failed: {str(e)[:200]}")    for wallet_type in WALLET_TYPES.get(exchange_name, []):        try:            bal = ex.fetch_balance(params={'type': wallet_type})            usdt = _extract_usdt(bal)            if usdt and usdt[0]:                candidates.append((wallet_type, usdt[0]))        except FATAL_EXCHANGE_ERRORS as e:            if raise_fatal:                raise TradeAborted(f"{exchange_name}: fatal error checking {wallet_type} USDT balance — {type(e).__name__}: {str(e)[:200]}")            log.error(f"{exchange_name}: fatal error checking {wallet_type} USDT balance — {type(e).__name__}: {str(e)[:200]}")        except Exception as e:            log.warning(f"{exchange_name} {wallet_type} fetch_balance failed: {str(e)[:200]}")    if not candidates:        return None, None    label, free = max(candidates, key=lambda c: c[1])    return free, labeldef get_available_asset_balance(exchange_name: str, asset_code: str, raise_fatal: bool = False):    ex = base.ensure_exchange(exchange_name)    if ex is None:        if raise_fatal:            raise TradeAborted(f"{exchange_name}: could not initialize exchange for {asset_code} balance check")        log.warning(f"{exchange_name}: could not initialize exchange for {asset_code} balance check")        return None, None    candidates = []    try:        bal = ex.fetch_balance()        amt = _extract_asset(bal, asset_code)        if amt:            candidates.append(('overview', amt))    except FATAL_EXCHANGE_ERRORS as e:        if raise_fatal:            raise TradeAborted(f"{exchange_name}: fatal error checking {asset_code} balance — {type(e).__name__}: {str(e)[:200]}")        log.error(f"{exchange_name}: fatal error checking {asset_code} balance — {type(e).__name__}: {str(e)[:200]}")    except Exception as e:        log.warning(f"{exchange_name} overview fetch_balance failed: {str(e)[:200]}")    for wallet_type in WALLET_TYPES.get(exchange_name, []):        try:            bal = ex.fetch_balance(params={'type': wallet_type})            amt = _extract_asset(bal, asset_code)            if amt:                candidates.append((wallet_type, amt))        except FATAL_EXCHANGE_ERRORS as e:            if raise_fatal:                raise TradeAborted(f"{exchange_name}: fatal error checking {asset_code} {wallet_type} balance — {type(e).__name__}: {str(e)[:200]}")            log.error(f"{exchange_name}: fatal error checking {asset_code} {wallet_type} balance — {type(e).__name__}: {str(e)[:200]}")        except Exception as e:            log.warning(f"{exchange_name} {wallet_type} fetch_balance failed: {str(e)[:200]}")    if not candidates:        return None, None    label, free = max(candidates, key=lambda c: c[1])    return free, label# ----------------------------------------------------------------------#  Order book & profit helpers (unchanged)# ----------------------------------------------------------------------def check_live_depth(buy_ex: str, sell_ex: str, symbol: str, capital_usd: float):    buy_venue  = base.ensure_exchange(buy_ex)    sell_venue = base.ensure_exchange(sell_ex)    if buy_venue is None or sell_venue is None:        return {'ok': False, 'reason': 'could not initialize buy/sell exchange for depth check'}    buy_ob  = base._fetch_order_book_safe(buy_ex,  buy_venue,  symbol)    sell_ob = base._fetch_order_book_safe(sell_ex, sell_venue, symbol)    if buy_ob is None or sell_ob is None:        return {'ok': False, 'reason': 'could not fetch fresh order book from one or both exchanges'}    asks = base._sort_book_side(buy_ob.get('asks', []) or [], 'asks')    bids = base._sort_book_side(sell_ob.get('bids', []) or [], 'bids')    buy_price,  _, buy_ok  = base.walk_book(asks, capital_usd)    sell_price, _, sell_ok = base.walk_book(bids, capital_usd)    if buy_price is None or sell_price is None or buy_price <= 0:        return {'ok': False, 'reason': 'order book too thin to price the full balance'}    return {        'ok': True,        'buy_price': buy_price,        'sell_price': sell_price,        'liquidity_ok': bool(buy_ok and sell_ok),    }def recalc_profit(trade_row: dict, buy_ex: str, sell_ex: str, symbol: str,                   capital_usd: float, buy_price: float, sell_price: float):    min_withdrawal = base._to_float(trade_row.get('min_withdrawal'))    gas_deducted   = base._to_float(trade_row.get('gas_deducted'))    buy_fee_rate  = base.get_trading_fee_rate(buy_ex,  symbol)    sell_fee_rate = base.get_trading_fee_rate(sell_ex, symbol)    profit = base.calc_arb_profit(        capital_usd, buy_price, sell_price,        fee_tokens=gas_deducted,        min_withdrawal_tokens=min_withdrawal,        buy_taker_rate=buy_fee_rate,        sell_taker_rate=sell_fee_rate,    )    if not profit:        return None    network, fee_usd = parse_usdt_transfer_fee(trade_row.get('usdt_transfer_fee'))    profit['usdt_transfer_network'] = network    profit['usdt_transfer_fee_usd'] = fee_usd or 0.0    profit['usdt_transfer_from']    = trade_row.get('usdt_holder')    profit['usdt_transfer_to']      = buy_ex    if fee_usd:        profit['net_pnl'] -= fee_usd        profit['roi_pct']  = (profit['net_pnl'] / profit['capital']) * 100 if profit['capital'] else 0.0    return profitdef validate_trade(capital_usd, min_withdrawal_met, liquidity_ok, profit):    if not capital_usd or capital_usd <= 0:        return False, "available USDT balance is zero"    if not min_withdrawal_met:        return False, "available balance does not satisfy the minimum withdrawal requirement"    if not liquidity_ok:        return False, "order book liquidity is insufficient for the full balance"    if profit is None or profit['net_pnl'] <= 0:        return False, "recalculated net profit is not positive"    if profit['roi_pct'] < MIN_ROI_PCT:        return False, f"ROI {profit['roi_pct']:+.2f}% is below the {MIN_ROI_PCT}% minimum threshold"    return True, Nonedef evaluate_trade(row: dict) -> dict:    pair = row.get('pair')    buy_ex, sell_ex = parse_buy_sell_exchanges(row.get('exchange'))    result = {        'pair': pair, 'buy_ex': buy_ex, 'sell_ex': sell_ex,        'holder_ex': None, 'capital': None, 'profit': None,        'valid': False, 'reason': None,    }    if not pair or not buy_ex or not sell_ex:        result['reason'] = f"could not parse trade row: {row}"        return result    holder_ex = get_capital_holder()    result['holder_ex'] = holder_ex    if not holder_ex:        result['reason'] = "bot_state.holds_usdt is not set"        return result    capital, _ = get_available_usdt_balance(holder_ex)    result['capital'] = capital    if capital is None:        result['reason'] = "could not retrieve available USDT balance"        return result    depth = check_live_depth(buy_ex, sell_ex, pair, capital)    if not depth['ok']:        result['reason'] = depth['reason']        return result    profit = recalc_profit(row, buy_ex, sell_ex, pair, capital, depth['buy_price'], depth['sell_price'])    if profit:        profit['_buy_price']  = depth['buy_price']        profit['_sell_price'] = depth['sell_price']    result['profit'] = profit    valid, reason = validate_trade(        capital_usd=capital,        min_withdrawal_met=profit['min_withdrawal_met'] if profit else False,        liquidity_ok=depth['liquidity_ok'],        profit=profit,    )    result['valid'] = valid    result['reason'] = reason    return resultdef print_trade_report(result: dict):    pair, buy_ex, sell_ex = result['pair'], result['buy_ex'], result['sell_ex']    holder_ex, capital, profit = result['holder_ex'], result['capital'], result['profit']    log.info(f"Pair: {pair}")    log.info(f"Buy exchange: {buy_ex}")    log.info(f"Sell exchange: {sell_ex}")    log.info(f"Capital holder: {holder_ex}")    log.info(f"Available USDT: {capital:.2f}" if capital is not None else "Available USDT: N/A")    log.info("")    log.info("Fetching fresh order books...")    log.info("")    if profit:        base_symbol = pair.split('/')[0] if pair else ""        log.info(f"Buy execution price: {base.fmt_price(profit['_buy_price'])}")        log.info(f"Sell execution price: {base.fmt_price(profit['_sell_price'])}")        log.info(f"Trading fee: -{profit['buy_fee_usd']:.4f} / -{profit['sell_fee_usd']:.4f} USDT")        log.info(f"Transfer fee: -{profit['usdt_transfer_fee_usd']:.4f} USDT")        log.info(f"Gas deduction: -{profit['gas_tokens']:.6f} {base_symbol}")        log.info(f"Minimum withdrawal: {profit['min_withdrawal_tokens']} {base_symbol}")        log.info(f"Tokens purchased: {profit['tokens_bought']:.6f}")        log.info(f"Tokens received: {profit['tokens_remaining']:.6f}")        log.info(f"Expected sell value: {profit['total_received']:.4f} USDT")        log.info(f"Net profit: {profit['net_pnl']:+.4f} USDT")        log.info(f"ROI: {profit['roi_pct']:+.2f}%")    log.info(f"Trade status: {'Valid' if result['valid'] else 'Invalid'}")    if not result['valid'] and result['reason']:        log.info(f"Reason: {result['reason']}")# ----------------------------------------------------------------------#  Retry helper# ----------------------------------------------------------------------def call_with_retries(fn, label, attempts=3, base_delay=5):    last_err = None    for attempt in range(1, attempts + 1):        try:            result = fn()            if attempt > 1:                log.info(f"[retry] {label}: succeeded on attempt {attempt}/{attempts}")            return result, None        except FATAL_EXCHANGE_ERRORS as e:            log.error(f"[retry] {label}: fatal error, not retrying — {type(e).__name__}: {str(e)[:200]}")            return None, e        except Exception as e:            last_err = e            log.warning(f"[retry] {label}: attempt {attempt}/{attempts} failed — {type(e).__name__}: {str(e)[:200]}")            if attempt < attempts:                delay = base_delay * (2 ** (attempt - 1))                log.info(f"[retry] {label}: retrying in {delay}s...")                time.sleep(delay)    return None, last_err# ----------------------------------------------------------------------#  Withdrawal helpers# ----------------------------------------------------------------------def initiate_withdrawal(exchange_name, asset, amount, address, network, tag=None):    ex = base.ensure_exchange(exchange_name)    if ex is None:        raise TradeAborted(f"{exchange_name}: could not initialize exchange for withdrawal")    if not address:        raise TradeAborted(f"{exchange_name}: no destination address configured for {asset} withdrawal")    if not amount or amount <= 0:        raise TradeAborted(f"{exchange_name}: withdrawal amount for {asset} is zero or invalid")    try:        amount = float(ex.currency_to_precision(asset, amount))    except Exception:        pass    params = {'network': network} if network else {}    def do_withdraw():        return ex.withdraw(asset, amount, address, tag, params)    log.info(f"[withdraw] {exchange_name}: requesting withdrawal of {amount:.8f} {asset} to {address} via {network or 'default'} network")    result, err = call_with_retries(        do_withdraw, f"{exchange_name} withdraw {asset}",        attempts=WITHDRAWAL_RETRY_ATTEMPTS, base_delay=WITHDRAWAL_RETRY_BASE_DELAY,    )    if err is not None:        raise TradeAborted(            f"{exchange_name}: withdrawal of {asset} failed after {WITHDRAWAL_RETRY_ATTEMPTS} attempts "            f"— {type(err).__name__}: {str(err)[:200]}"        )    wd_id = (result or {}).get('id')    log.info(f"[withdraw] ✅ {exchange_name}: withdrawal accepted — id={wd_id}  amount={amount:.8f} {asset}  -> {address}")    return result, amountdef monitor_transfer(exchange_name, asset, baseline_amount, expected_increase, label):    target = baseline_amount + max(expected_increase, 0.0) * BALANCE_ARRIVAL_TOLERANCE    log.info(f"[transfer] {label}: waiting for {asset} on {exchange_name} to reach >= {target:.8f} (baseline {baseline_amount:.8f})")    while True:        if asset.upper() == 'USDT':            current, _ = get_available_usdt_balance(exchange_name, raise_fatal=True)        else:            current, _ = get_available_asset_balance(exchange_name, asset, raise_fatal=True)        if current is None:            log.warning(f"[transfer] {exchange_name}: could not read {asset} balance — retrying in {CHECK_INTERVAL_SEC}s")            time.sleep(CHECK_INTERVAL_SEC)            continue        log.info(f"[transfer] {exchange_name}: {asset} balance = {current:.8f}  (target {target:.8f})")        if current >= target:            log.info(f"[transfer] ✅ {label} confirmed on {exchange_name}")            return current        time.sleep(CHECK_INTERVAL_SEC)# ----------------------------------------------------------------------#  Fetch coin withdrawal info – now sourced identically to analyzer.py# ----------------------------------------------------------------------def fetch_coin_withdrawal_info(exchange_name, code, network=None):    """    Returns {'fee': float, 'min': float} for the given asset/network.    This now uses the exact same lookup path analyzer.py uses when it first    verifies a pair and computes withdrawal_fee / withdrawal_min_tokens:      1. base.get_currencies(exchange_name) — the same cached (30 min TTL)         fetch_currencies() call analyzer relies on everywhere.      2. Only if that currency has no network data at all, fall back to         base._fallback_networks() (fetch_deposit_withdraw_fee/fees) —         same fallback, same order, same conditions analyzer uses.      3. Match the network the same way analyzer does, via         base.normalize_network(), so 'BEP20' vs 'BSC' vs 'BNB Smart Chain'         etc. all resolve to the same entry analyzer already picked.    This guarantees trader.py can never disagree with analyzer.py about the    fee/minimum for a given exchange+coin+network, because they now both read    from the same source in the same way, instead of trader.py maintaining    its own separate (and differently-ordered) API call sequence.    """    code = code.upper()    currencies = base.get_currencies(exchange_name)    cur = currencies.get(code)    if not isinstance(cur, dict):        raise TradeAborted(f"{exchange_name}: '{code}' not found in currency list")    networks = cur.get('networks') or {}    if not networks:        networks = base._fallback_networks(exchange_name, code)    if not networks:        raise TradeAborted(f"{exchange_name}: no network data available for {code}")    target_norm = base.normalize_network(network) if network else None    match = None    for net_code, net_data in networks.items():        if not isinstance(net_data, dict):            continue        if target_norm is None or base.normalize_network(net_code) == target_norm:            match = net_data            break    if match is None:        raise TradeAborted(f"{exchange_name}: no matching network '{network}' found for {code}")    fee    = base._to_float(match.get('fee'))    min_wd = base._to_float(((match.get('limits') or {}).get('withdraw') or {}).get('min'))    if fee is None or min_wd is None:        missing = []        if fee is None:            missing.append('fee')        if min_wd is None:            missing.append('min')        raise TradeAborted(            f"{exchange_name}: could not determine {'/'.join(missing)} for {code} on network {network or 'default'}"        )    return {'fee': fee, 'min': min_wd}# ----------------------------------------------------------------------#  Order execution helpers# ----------------------------------------------------------------------def confirm_order_filled(ex, exchange_name, symbol, order):    order_id = order.get('id')    status = order.get('status')    filled = order.get('filled') or 0.0    if status == 'closed' and filled > 0:        return order    if not order_id:        if filled > 0:            log.warning(f"[order] {exchange_name}: order has no id but reports filled={filled} — proceeding")            return order        raise TradeAborted(f"{exchange_name}: order response has no id and no fill — cannot confirm execution")    waited = 0    while waited < ORDER_POLL_TIMEOUT_SEC:        time.sleep(ORDER_POLL_INTERVAL_SEC)        waited += ORDER_POLL_INTERVAL_SEC        try:            fresh = ex.fetch_order(order_id, symbol)        except Exception as e:            log.warning(f"[order] {exchange_name}: fetch_order poll failed — {str(e)[:150]}")            continue        status = fresh.get('status')        filled = fresh.get('filled') or 0.0        order = fresh        log.info(f"[order] {exchange_name}: order {order_id} status={status} filled={filled}")        if status == 'closed' and filled > 0:            return order    if filled > 0:        log.warning(f"[order] {exchange_name}: order {order_id} not fully closed after {ORDER_POLL_TIMEOUT_SEC}s but filled={filled} — proceeding with partial fill")        return order    raise TradeAborted(f"{exchange_name}: order {order_id} did not fill within {ORDER_POLL_TIMEOUT_SEC}s")def execute_market_buy(buy_ex, symbol, capital_usd):    """    Market buy using the safest unified method first:    1. create_market_buy_order_with_cost (modern ccxt, handles exchange-specific params)    2. Fallback to createMarketBuyOrderRequiresPrice logic.    """    ex = base.ensure_exchange(buy_ex)    if ex is None:        raise TradeAborted(f"{buy_ex}: could not initialize exchange for market buy")    # Strategy 1: Unified cost-based market buy (works across all exchanges)    if hasattr(ex, 'create_market_buy_order_with_cost'):        def try_unified_buy():            return ex.create_market_buy_order_with_cost(symbol, capital_usd)        log.info(f"[order] {buy_ex}: attempting unified market buy with cost={capital_usd:.4f} USDT")        result, err = call_with_retries(            try_unified_buy,            f"{buy_ex} unified market buy {symbol}",            attempts=1,  # if it fails we fallback immediately            base_delay=0,        )        if result is not None:            order = confirm_order_filled(ex, buy_ex, symbol, result)            log_after_buy(order, buy_ex, symbol)            return order        log.warning(f"[order] {buy_ex}: unified buy not supported or failed, falling back to legacy")    # Strategy 2: Legacy createMarketBuyOrderRequiresPrice logic    def do_buy():        if ex.has.get('createMarketBuyOrderRequiresPrice') is False:            return ex.create_market_buy_order(symbol, capital_usd)        ticker = ex.fetch_ticker(symbol)        ask = ticker.get('ask') or ticker.get('last')        if not ask or ask <= 0:            raise Exception(f"{buy_ex}: could not determine current ask price for {symbol}")        est_amount = (capital_usd / ask) * 0.999        return ex.create_market_buy_order(symbol, est_amount)    log.info(f"[order] {buy_ex}: submitting MARKET BUY (legacy) using {capital_usd:.4f} USDT")    result, err = call_with_retries(        do_buy, f"{buy_ex} market buy {symbol}",        attempts=ORDER_RETRY_ATTEMPTS, base_delay=ORDER_RETRY_BASE_DELAY,    )    if err is not None:        raise TradeAborted(f"{buy_ex}: market buy failed after {ORDER_RETRY_ATTEMPTS} attempts — {type(err).__name__}: {str(err)[:200]}")    order = confirm_order_filled(ex, buy_ex, symbol, result)    log_after_buy(order, buy_ex, symbol)    return orderdef log_after_buy(order, exchange_name, symbol):    filled_amount = order.get('filled') or 0.0    avg_price = order.get('average') or order.get('price')    log.info(        f"[order] ✅ {exchange_name}: BUY filled — {filled_amount:.8f} {symbol.split('/')[0]} "        f"@ avg {base.fmt_price(avg_price) if avg_price else 'N/A'}"    )def execute_market_sell(sell_ex, symbol, amount):    ex = base.ensure_exchange(sell_ex)    if ex is None:        raise TradeAborted(f"{sell_ex}: could not initialize exchange for market sell")    try:        amount = float(ex.amount_to_precision(symbol, amount))    except Exception:        pass    def do_sell():        return ex.create_market_sell_order(symbol, amount)    log.info(f"[order] {sell_ex}: submitting MARKET SELL {amount:.8f} {symbol}")    result, err = call_with_retries(        do_sell, f"{sell_ex} market sell {symbol}",        attempts=ORDER_RETRY_ATTEMPTS, base_delay=ORDER_RETRY_BASE_DELAY,    )    if err is not None:        raise TradeAborted(f"{sell_ex}: market sell failed after {ORDER_RETRY_ATTEMPTS} attempts — {type(err).__name__}: {str(err)[:200]}")    order = confirm_order_filled(ex, sell_ex, symbol, result)    filled_amount = order.get('filled') or 0.0    received_usd = order.get('cost') or (filled_amount * (order.get('average') or 0))    log.info(f"[order] ✅ {sell_ex}: SELL filled — {filled_amount:.8f} sold for ~{received_usd:.4f} USDT")    return orderdef update_bot_state_holder(exchange_name):    holder = (exchange_name or "").strip()    try:        sb = base._get_supabase_cached()        sb.table("bot_state").update({"holds_usdt": holder}).eq("id", 1).execute()        log.info(f"[state] ✅ bot_state.holds_usdt updated -> '{holder}'")        return True    except Exception as e:        log.error(f"[state] failed to update bot_state.holds_usdt -> '{holder}': {str(e)[:200]}")        return Falsedef revalidate_until_valid(row, buy_ex, sell_ex, pair):    while True:        capital, _ = get_available_usdt_balance(buy_ex)        if not capital or capital <= 0:            log.warning(f"[revalidate] {buy_ex}: no available USDT balance yet — waiting {CHECK_INTERVAL_SEC}s")            time.sleep(CHECK_INTERVAL_SEC)            continue        depth = check_live_depth(buy_ex, sell_ex, pair, capital)        if not depth['ok']:            log.info(f"[revalidate] {pair}: {depth['reason']} — waiting {CHECK_INTERVAL_SEC}s")            time.sleep(CHECK_INTERVAL_SEC)            continue        profit = recalc_profit(row, buy_ex, sell_ex, pair, capital, depth['buy_price'], depth['sell_price'])        valid, reason = validate_trade(            capital_usd=capital,            min_withdrawal_met=profit['min_withdrawal_met'] if profit else False,            liquidity_ok=depth['liquidity_ok'],            profit=profit,        )        if profit:            log.info(f"[revalidate] {pair}: net profit {profit['net_pnl']:+.4f} USDT  ROI {profit['roi_pct']:+.2f}%")        if valid:            log.info(f"[revalidate] ✅ {pair}: still valid — proceeding to buy")            return capital, profit        log.info(f"[revalidate] {pair}: not valid yet — {reason} — checking again in {CHECK_INTERVAL_SEC}s")        time.sleep(CHECK_INTERVAL_SEC)def wait_for_profitable_sell(sell_ex, pair, base_asset, held, capital_spent):    while True:        ex = base.ensure_exchange(sell_ex)        if ex is None:            raise TradeAborted(f"{sell_ex}: could not initialize exchange for sell-side pricing")        ob = base._fetch_order_book_safe(sell_ex, ex, pair)        if ob is None:            log.warning(f"[sell] {sell_ex}: could not fetch order book — retrying in {CHECK_INTERVAL_SEC}s")            time.sleep(CHECK_INTERVAL_SEC)            continue        bids = base._sort_book_side(ob.get('bids', []) or [], 'bids')        target_usd = held * bids[0][0] if bids else 0        sell_price, _, _ = base.walk_book(bids, target_usd)        if not sell_price:            log.warning(f"[sell] {sell_ex}: order book too thin to price {base_asset} — retrying in {CHECK_INTERVAL_SEC}s")            time.sleep(CHECK_INTERVAL_SEC)            continue        sell_fee_rate = base.get_trading_fee_rate(sell_ex, pair)        gross_usd    = held * sell_price        sell_fee_usd = gross_usd * sell_fee_rate        net_pnl      = gross_usd - sell_fee_usd - capital_spent        log.info(            f"[sell] {pair}: {held:.8f} {base_asset} @ {base.fmt_price(sell_price)}  "            f"gross {gross_usd:.4f}  fee -{sell_fee_usd:.4f}  net {net_pnl:+.4f} USDT "            f"(min required {base.MIN_STORE_PROFIT_USD})"        )        if net_pnl >= base.MIN_STORE_PROFIT_USD:            log.info(f"[sell] ✅ {pair}: profit threshold met — executing market sell")            return execute_market_sell(sell_ex, pair, held)        time.sleep(CHECK_INTERVAL_SEC)# ----------------------------------------------------------------------#  Main trade execution flow# ----------------------------------------------------------------------def execute_trade(row, result):    pair      = result['pair']    buy_ex    = result['buy_ex']    sell_ex   = result['sell_ex']    holder_ex = result['holder_ex']    base_asset = pair.split('/')[0]    log.info("=" * 60)    log.info(f"EXECUTING TRADE: {pair}   {buy_ex} -> {sell_ex}   holder={holder_ex}")    log.info("=" * 60)    try:        network, transfer_fee_usd = parse_usdt_transfer_fee(row.get('usdt_transfer_fee'))        usdt_dest_address = row.get('usdt_d_address')        # ----- Step 1: USDT transfer (if needed) -----        if holder_ex.lower() == buy_ex.lower():            log.info(f"[step1] {holder_ex} already holds the capital and is the buy exchange — skipping USDT transfer")        else:            withdraw_amount, _ = get_available_usdt_balance(holder_ex)            if not withdraw_amount or withdraw_amount <= 0:                raise TradeAborted(f"{holder_ex}: no available USDT balance to withdraw")            buy_usdt_baseline, _ = get_available_usdt_balance(buy_ex)            buy_usdt_baseline = buy_usdt_baseline or 0.0            log.info(f"[step1] transferring {withdraw_amount:.4f} USDT: {holder_ex} -> {buy_ex} via {network or 'default'} network")            _, actual_amount = initiate_withdrawal(holder_ex, 'USDT', withdraw_amount, usdt_dest_address, network)            log.info(f"[step2] waiting for USDT deposit to arrive on {buy_ex}")            expected_increase = actual_amount - (transfer_fee_usd or 0.0)            monitor_transfer(buy_ex, 'USDT', buy_usdt_baseline, expected_increase, 'USDT transfer')        # ----- Step 2: Revalidate & buy -----        log.info(f"[step3] revalidating {pair} before buying")        capital, profit = revalidate_until_valid(row, buy_ex, sell_ex, pair)        log.info(f"[step4] executing market buy on {buy_ex} with {capital:.4f} USDT")        buy_order = execute_market_buy(buy_ex, pair, capital)        tokens_bought = buy_order.get('filled') or 0.0        capital_spent = buy_order.get('cost') or capital        # ----- Step 3: Post-buy PnL estimate (informational only — never aborts) -----        # The tokens are already bought and sitting on buy_ex by this point. Aborting        # here would strand them there with no sell-back and a stale bot_state, so        # instead we always proceed to move them to sell_ex. wait_for_profitable_sell()        # on the sell side already loops until the price is actually favorable before        # executing the sell — an unfavorable estimate here just means a longer wait        # there, not a reason to abandon a position we already hold.        log.info(f"[step4] post-buy PnL estimate")        gas_tokens = base._to_float(row.get('gas_deducted')) or 0.0        net_sellable = max(tokens_bought - gas_tokens, 0.0)        if net_sellable == 0:            raise TradeAborted(f"After gas deduction ({gas_tokens}), no tokens remain to sell")        try:            sell_orderbook = base._fetch_order_book_safe(sell_ex, base.ensure_exchange(sell_ex), pair)            bids = base._sort_book_side((sell_orderbook or {}).get('bids', []) or [], 'bids')            sell_price, _, _ = base.walk_book(bids, tokens_bought * bids[0][0]) if bids else (None, None, None)            if sell_price:                sell_fee_rate = base.get_trading_fee_rate(sell_ex, pair)                gross_sell = net_sellable * sell_price                sell_fee_actual = gross_sell * sell_fee_rate                net_pnl = gross_sell - sell_fee_actual - capital_spent                status = "still profitable" if net_pnl > 0 else "NOT currently profitable — moving tokens anyway, sell-side will wait"                log.info(f"[step4] post-buy PnL estimate: {net_pnl:+.4f} USDT ({status})")            else:                log.warning(f"[step4] {sell_ex}: order book too thin to estimate post-buy PnL — moving tokens anyway")        except Exception as e:            log.warning(f"[step4] post-buy PnL estimate failed: {str(e)[:200]} — moving tokens anyway")        log.info(f"[step4] moving bought tokens to {sell_ex}; sell-side will wait for a profitable price before selling")        # ----- Step 4: Withdraw token to sell exchange -----        withdraw_token_amount = net_sellable        coin_network = row.get('coin_wd_network')        coin_dest_address = row.get('coin_d_address')        # Fetch withdrawal fee & minimum for the token/network        wd_info = fetch_coin_withdrawal_info(buy_ex, base_asset, coin_network)        coin_fee = wd_info['fee']        min_wd = wd_info['min']        if withdraw_token_amount < min_wd:            raise TradeAborted(                f"Token withdrawal amount {withdraw_token_amount:.8f} below minimum {min_wd} for {base_asset} on {coin_network or 'default'} network"            )        net_arrival = withdraw_token_amount - coin_fee        if net_arrival <= 0:            raise TradeAborted(                f"After subtracting withdrawal fee {coin_fee}, net arrival is {net_arrival:.8f} — aborting"            )        log.info(f"[step4] coin withdrawal fee {coin_fee} {base_asset}; net expected arrival = {net_arrival:.8f}")        sell_token_baseline, _ = get_available_asset_balance(sell_ex, base_asset)        sell_token_baseline = sell_token_baseline or 0.0        log.info(f"[step4] withdrawing {withdraw_token_amount:.8f} {base_asset}: {buy_ex} -> {sell_ex} via {coin_network or 'default'} network")        _, actual_token_amount = initiate_withdrawal(buy_ex, base_asset, withdraw_token_amount, coin_dest_address, coin_network)        log.info(f"[step4] waiting for {base_asset} deposit to arrive on {sell_ex}")        monitor_transfer(sell_ex, base_asset, sell_token_baseline, net_arrival, f"{base_asset} transfer")        # ----- Step 5: Monitor & sell -----        log.info(f"[step5] monitoring {pair} for a profitable sell on {sell_ex}")        held, _ = get_available_asset_balance(sell_ex, base_asset)        held = held or net_arrival        wait_for_profitable_sell(sell_ex, pair, base_asset, held, capital_spent)        log.info(f"[step6] updating bot_state.holds_usdt -> '{sell_ex}'")        update_bot_state_holder(sell_ex)        log.info("[step7] cleaning up trade_coins row and restarting scan loop")        delete_trade_coin(row.get('id'))        log.info("=" * 60)        log.info(f"TRADE COMPLETE: {pair}   capital now held on '{sell_ex}'")        log.info("=" * 60)        return True    except TradeAborted as e:        log.error(f"TRADE ABORTED: {pair} — {e}")        log.error("Restarting trader and resuming scan...")        return False    except Exception as e:        log.error(f"TRADE ABORTED (unexpected error): {pair} — {type(e).__name__}: {str(e)[:300]}")        log.error("Restarting trader and resuming scan...")        return Falsedef run_once():    rows = load_all_trade_coins()    total = len(rows)    log.info("-" * 40)    log.info("Trader started")    log.info("-" * 40)    log.info(f"Loaded {total} trade opportunities.")    log.info("")    if total == 0:        log.info("Finished.")        return    valid_count = 0    invalid_count = 0    deleted_count = 0    executed = False    processed = 0    for i, row in enumerate(rows, start=1):        processed = i        log.info(f"Checking trade {i}/{total}...")        result = evaluate_trade(row)        print_trade_report(result)        if result['valid']:            valid_count += 1            log.info("")            log.info("Trade status: Valid — beginning execution...")            log.info("")            executed = execute_trade(row, result)            break        else:            invalid_count += 1            log.info("Deleting invalid opportunity...")            if delete_trade_coin(row.get('id')):                deleted_count += 1        log.info("")    remaining = total - deleted_count - (1 if executed else 0)    log.info("Finished.")    log.info("")    log.info(f"Processed: {processed}")    log.info(f"Valid: {valid_count}")    log.info(f"Invalid: {invalid_count}")    log.info(f"Deleted: {deleted_count}")    log.info(f"Executed: {'yes' if executed else 'no'}")    log.info(f"Remaining in trade_coins: {remaining}")def main():    base.set_exchange_mode('trader')    while True:        try:            run_once()        except Exception as e:            log.error(f"trader.py: unexpected error in run cycle: {str(e)[:300]}")        log.info("")        log.info(f"Next check in {CHECK_INTERVAL_SEC}s...")        log.info("")        time.sleep(CHECK_INTERVAL_SEC)if __name__ == "__main__":    try:        main()    except KeyboardInterrupt:        log.info("trader.py stopped.")